function _loading_(callback) {
  // to login
  var url = location.href;
  if (url.indexOf('#/user-login') > 0 || url.endsWith('/') || url.endsWith('#')) {
    var encTid = url.indexOf('?t=') > 0 ? getParamValFromUrl(url, 't') : null;
    fetchLoginBg(encTid, callback);
  } else if (url.indexOf('?t=') > 0 || url.indexOf('?encSid=') > 0) {
    $.data.user = {};
    var t = getParamValFromUrl(url, 't');
    fetchLoginBg(t, callback);
  } else {
    // refresh page
    //-- 加载用户数据
    if ($.Util.cookie.get($.Conf.Keys.LOGIN_FLAG)) {
      $.Req.service($.SvName.INIT_DATA_LOAD, { clientType: 1 }, function (ret) {
        if (ret.user.staffId && ret.user.memberId) {
          var loginAs = $.Util.cookie.get($.Conf.CookieKeys.LOGIN_AS);
          if (loginAs === 'member') {
            ret.user.staffId = null;
            ret.user.isTenantOwner = false;
            ret.user.isShopOwner = false;
          } else {
            ret.user.memberId = null;
          }
        }

        $.data.user = ret.user;
        $.data.user.wxId = $.Util.cookie.get($.Conf.CookieKeys.USER_WXID);
        $.data.tenant = ret.tenant;
        $.data.shop = ret.shop;
        $.data.clientVersion = ret.clientVersion;
        $.data.shopList = ret.shopList;
        document.title = ret.shop ? ret.shop.shopName : ret.tenant.tenantName;
        // if ($.data.shop.addrProvince !== 820000) { // 澳门
        //   delete $.Dict.CardPaymentChannel[8];
        //   delete $.Dict.CardPaymentChannel[9];
        //   delete $.Dict.CardPaymentChannelForView[8];
        //   delete $.Dict.CardPaymentChannelForView[9];
        // }
        callback();
      }, false, function (err) {
        callback();
      });
    } else {
      callback();
    }
  }
}

function fetchLoginBg(encTid, callback) {
  /*
    if (!encTid) {
      encTid = $.Util.cookie.get($.Conf.CookieKeys.LOGIN_TID);
      if (!encTid) {
        $.data.misc.loginBgUrl = $.Conf.IMG_LIB_URL + '/jzg-m-bg/login-bg-1.jpg';
        callback();
        return;
      }
    }
    let args = {encTid: encTid};
    $.Req.service($.SvName.TENANT_MOBILE_LOGIN_BG_QUERY, args, (ret) => {
      let bgId = 1;
      if (ret.mloginBg) {
        bgId = ret.mloginBg;
      }
      $.data.misc.loginBgUrl = $.Conf.IMG_LIB_URL + '/jzg-m-bg/login-bg-' + bgId + '.jpg';
      callback();
    });
  */
  if (!encTid) {
    encTid = $.Util.cookie.get($.Conf.CookieKeys.LOGIN_TID);
    if (!encTid) {
      $.data.misc.loginBgUrl = $.Conf.IMG_LIB_URL + '/jzg-m-bg/login-bg-1.jpg';
      callback();
      return;
    }
  }
  var args = { encTid: encTid };
  $.Req.service($.SvName.TENANT_MOBILE_LOGIN_BG_QUERY, args, function (ret) {
    if (ret.mloginStyle) $.data.misc.mloginStyle = parseInt(ret.mloginStyle);
    if (ret.mloginBg) {
      $.data.misc.mloginBgId = ret.mloginBg;
    }
    if (ret.mloginTitle) $.data.misc.mloginTitle = ret.mloginTitle;
    if (ret.mloginSubtitle) $.data.misc.mloginSubtitle = ret.mloginSubtitle;
    var loginBgUrl = null;
    if (parseInt(ret.mloginStyle) == 3 || parseInt(ret.mloginStyle) == 4) {
      loginBgUrl = $.Conf.IMG_LIB_URL + '/jzg-m-bg/s' + parseInt(ret.mloginStyle) + '/' + $.data.misc.mloginBgId + '.jpg';
    } else {
      loginBgUrl = $.Conf.IMG_LIB_URL + '/jzg-m-bg/login-bg-' + $.data.misc.mloginBgId + '.jpg';
    }
    $.data.misc.loginBgUrl = loginBgUrl;
    callback();
  });
}

function getParamValFromUrl(url, paramName) {
  var paramVal = null;
  var queryList = url.split("?");
  for (var i = 1; i < queryList.length; i++) {
    var query = queryList[i];
    var queryArr = query.split("&");
    queryArr.forEach(function (item) {
      var key = item.split("=")[0];
      var val = item.split("=")[1];
      if (key === paramName) {
        paramVal = decodeURIComponent(val);
        return val;
      }
    });
  }

  if (paramVal) paramVal = paramVal.replace(/ /g, "+");

  return paramVal;
}

function _initLoadingImg_() {
  var brwSize = $.Util.getBrowserSize();
  var pageWidth = brwSize.pageWidth;
  var clientHeight = brwSize.pageHeight;
  var maskCont = document.createElement("div");

  maskCont.id = "_mask_cont_";
  maskCont.innerHTML = '<img src="/static/img/loading.gif"/>';
  maskCont.style.display = 'none';
  document.body.appendChild(maskCont);
  var contHeight = maskCont.offsetHeight;
  var contWidth = maskCont.offsetWidth;
  maskCont.style.left = pageWidth / 2 - contWidth / 2 - 10 + "px";
  maskCont.style.top = clientHeight / 2 - contHeight / 2 + "px";
}

